      v.x += b2_s[g * 32 + (i0 + 0) / HW]; v.y += b2_s[g * 32 + (i0 + 1) / HW]; v.z += b2_s[g * 32 + (i0 + 2) / HW]; v.w += b2_s[g * 32 + (i0 + 3) / HW];
