    }
  }
  asm volatile("fence.proxy.async.global;" ::: "memory");
  STAMP(1);
  cg::grid_group grid = cg::this_grid();
  grid.sync();
  STAMP(2);
  unsigned it = 0;
  if (tid == 0) { asm volatile("fence.proxy.async.global;" ::: "memory"); ws_prime(sm, p, full, 0, 0, WS_WPRE, false, true, is1); ws_prime(sm, p, full, 0, WS_WPRE, WS_S, true, true, is1); }
  for (int t = tid; t < Tp; t += WS_NT) {
    const int im = t / HWp, hw = t - im * HWp; float mu = 0.f, rs = 0.f;
    if (hw < HW) {
