    constexpr int WN = CF::WN1, MTW = CF::MTW1, NTW = CF::NTW1;
    const int wm = warp & 7, wn = warp >> 3, g = lane >> 2, q = lane & 3;
    const int NB1 = p.NB1, TpR = Tp + 4;
    float* raw = reinterpret_cast<float*>(sm); __half* hst = reinterpret_cast<__half*>(sm + p.o_hst);
    for (int pass = 0; pass < p.npass; pass++) {
      WSIssue isp = is1; isp.wy = n0 + pass * NB1;
      if (pass > 0 && tid == 0) { asm volatile("fence.proxy.async.shared::cta;" ::: "memory"); ws_prime(sm, p, full, it, 0, WS_S, true, true, isp); }
      float acc[MTW][NTW][4];
      ws_gemm<WN, MTW, NTW, 1, 1>(p, sm, full, it, p.nk1, isp, NB1, lnw_s, lnb_s, nullptr, s1_s, c1_s, acc, warp, lane, pass == 0 ? 32 : -1);
      if (pass == 0) STAMP(9);
      if (WN == 2 || warp < 8) {
#pragma unroll
        for (int i = 0; i < MTW; i++) {
          if (wm * MTW + i < p.MT) {
            const int mt = wm * MTW + i;
#pragma unroll
            for (int jj = 0; jj < NTW; jj++)
#pragma unroll
              for (int r = 0; r < 4; r++) { const int t = mt * 16 + g + 8 * (r >> 1), n = (wn * NTW + jj) * 8 + 2 * q + (r & 1); raw[n * TpR + t] = acc[i][jj][r]; }
