        float sq = 0.f;
        for (int hw = lane; hw < HWp; hw += 32) {
          const int t = im * HWp + hw; float v = 0.f;
          if (hw < HW) v = gelu_f(fmaf(rs_s[t], raw[n * TpR + t] - mu_s[t] * s1n, c1n));
          const __half hv = __float2half_rn(v); const float hf = __half2float(hv); sq = fmaf(hf, hf, sq); hst[n * Tpp + t] = hv;
        }
        sq = warp_sum(sq);
        if (lane == 0) { const float gfv = sqrtf(sq); p.gf[(size_t)(tile1 * NI + im) * C4 + isp.wy + n] = gfv; atomicAdd(gsum_s + im, gfv); }
      }
