      if (pass == 0) STAMP(14);
      { const uint4* src = reinterpret_cast<const uint4*>(hst); uint4* dst = reinterpret_cast<uint4*>(p.hid + ((size_t)tile1 * C4 + isp.wy) * Tpp);
        const int n16 = NB1 * Tpp / 8; for (int e = tid; e < n16; e += WS_NT) dst[e] = src[e]; }
      if (tid < 96) { s1_s[tid] = 0.f; c1_s[tid] = 0.f; }
