  is2.wbytes = p.CS * 128; is2.abytes = 32 * Tpp * 2;
  if (tid == 0) { asm volatile("fence.proxy.async.shared::cta;" ::: "memory"); ws_prime(sm, p, full, it, 0, WS_S, true, false, is2); }
  asm volatile("fence.proxy.async.global;" ::: "memory");
  STAMP(3);
  grid.sync();
  STAMP(4);
  if (tid == 0) { asm volatile("fence.proxy.async.global;" ::: "memory"); ws_prime(sm, p, full, it, 0, WS_S, false, true, is2); }
  if (warp < NI) {
    const int b = tile2 * NI + warp; float s = 0.f;
    for (int i = lane; i < p.NS1; i += 32) s += __ldcg(p.gpart + (size_t)b * p.NS1 + i);
    s = warp_sum(s); if (lane == 0) inv_s[warp] = 1.f / (s / (float)C4 + p.eps);
  }
