  for (int e = tid; e < NI * p.KSL; e += WS_NT) {
    const int im = e / p.KSL, kl = e - im * p.KSL;
    const float gfv = __ldcg(p.gf + (size_t)(tile2 * NI + im) * C4 + k0 + kl);
