  }
  __syncthreads();
  STAMP(10);
  {
    constexpr int WN = CF::WN2, MTW = CF::MTW2, NTW = CF::NTW2;
    const int wm = warp & 7, wn = warp >> 3, g = lane >> 2, q = lane & 3;
    float acc[MTW][NTW][4];
    ws_gemm<WN, MTW, NTW, 2, CF::NI>(p, sm, full, it, p.nk2, is2, p.CS, nullptr, gb_s, stab, gbd_s, nullptr, acc, warp, lane, 80);
    STAMP(5);
    __syncthreads();
    float* stg = reinterpret_cast<float*>(sm); const int CS = p.CS;
    if (WN == 2 || warp < 8) {
#pragma unroll
      for (int i = 0; i < MTW; i++) {
        if (wm * MTW + i < p.MT) {
          const int mt = wm * MTW + i;
#pragma unroll
          for (int jj = 0; jj < NTW; jj++)
#pragma unroll
            for (int r = 0; r < 4; r++) {
              const int t = mt * 16 + g + 8 * (r >> 1); const int im = t / HWp, hw = t - im * HWp;
              if (hw < HW) { const int cl = (wn * NTW + jj) * 8 + 2 * q + (r & 1); stg[(im * CS + cl) * HW + hw] = acc[i][jj][r] + gbd_s[cl]; }
            }
        }
      }
    }
    __syncthreads();
    const int n4 = CS * HW / 4;
    for (int e = tid; e < NI * n4; e += WS_NT) {
      const int im = e / n4, r = e - im * n4; const float4 v = reinterpret_cast<const float4*>(stg)[e];
