struct WSRow { int B, C, H, W, NI, BN, npass, CS, KS, cfg; };
static const WSRow kWSRows[6] = {
    {2, 768, 7, 7, 2, 24, 1, 48, 8, 0},   {8, 768, 7, 7, 2, 96, 1, 96, 4, 1},     {16, 768, 7, 7, 4, 96, 1, 96, 4, 2},
    {32, 768, 7, 7, 4, 192, 2, 96, 2, 2}, {8, 384, 14, 14, 1, 96, 1, 96, 4, 3}, {16, 384, 14, 14, 1, 192, 2, 96, 2, 3}};
struct WSArgs { const float *x, *dww, *dwb, *lnw, *lnb, *w1, *b1, *gw, *gb, *w2, *b2; float* out; void* ws; unsigned long long* stamps; int B, C, H, W; float eps, ln_eps; int dbg; };
static inline size_t ws_al(size_t v, size_t a) { return (v + a - 1) / a * a; }
struct WSPlan { WSRow r; int HW, C4, G, units, ntile, NS1, NCS, KSL, P, UPC, HWp, Tp, Tpp, NB1; size_t o_d16, o_part, o_hid, o_gf, o_gpart, ws_bytes; int o_A, o_Bh, o_cx, o_cw, o_cd, o_hst, o_tab, smem; };
static bool ws_plan(int B, int C, int H, int W, WSPlan& pl) {
  int idx = -1;
  for (int i = 0; i < 6; i++) if (kWSRows[i].B == B && kWSRows[i].C == C && kWSRows[i].H == H && kWSRows[i].W == W) idx = i;
  if (idx < 0) return false;
